"""
Heuristic Quality Filter for Source Code
Applies BigCode / StarCoder quality filters:
- Line length constraints (minified / obfuscated code elimination)
- Alphanumeric character density
- Autogenerated code marker detection
- Comment-to-code balance
"""

import re
from typing import Tuple, Dict, Any, List

# Common autogenerated code signatures to reject
AUTOGEN_PATTERNS = [
    re.compile(r"auto-generated", re.IGNORECASE),
    re.compile(r"automatically generated", re.IGNORECASE),
    re.compile(r"generated by (?:protobuf|protoc|thrift|openapi|swagger|grpc)", re.IGNORECASE),
    re.compile(r"this file was generated", re.IGNORECASE),
    re.compile(r"code generated by .+ do not edit", re.IGNORECASE),
    re.compile(r"generated from .+ by .+", re.IGNORECASE),
]


def is_autogenerated_code(text: str, head_lines: int = 20) -> bool:
    """Check the top lines of a file for automated code-generation markers."""
    lines = text.split("\n")[:head_lines]
    header = "\n".join(lines)
    for pattern in AUTOGEN_PATTERNS:
        if pattern.search(header):
            return True
    return False


def is_high_quality_code(
    text: str,
    max_line_length: int = 1000,
    min_mean_line_length: float = 10.0,
    max_mean_line_length: float = 120.0,
    min_alphanumeric_ratio: float = 0.35,
    max_comment_ratio: float = 0.85,
) -> Tuple[bool, str]:
    """
    Evaluates source code against heuristic quality criteria.
    
    Returns:
        is_valid: True if code passes all quality checks
        reason: Explanation if rejected
    """
    if len(text.strip()) < 50:
        return False, "file_too_short"

    if is_autogenerated_code(text):
        return False, "autogenerated_code"

    lines = text.split("\n")
    num_lines = len(lines)
    if num_lines == 0:
        return False, "empty_lines"

    # Check maximum line length (catches minified JavaScript, long base64 strings)
    longest_line = max(len(ln) for ln in lines)
    if longest_line > max_line_length:
        return False, f"line_too_long ({longest_line} > {max_line_length})"

    # Mean line length
    mean_len = sum(len(ln) for ln in lines) / num_lines
    if mean_len < min_mean_line_length or mean_len > max_mean_line_length:
        return False, f"abnormal_mean_line_length ({mean_len:.1f})"

    # Alphanumeric ratio (filters symbol garbage, base64 dumps, binary noise)
    total_chars = len(text)
    alnum_chars = sum(1 for c in text if c.isalnum())
    alnum_ratio = alnum_chars / total_chars if total_chars > 0 else 0.0

    if alnum_ratio < min_alphanumeric_ratio:
        return False, f"low_alphanumeric_ratio ({alnum_ratio:.2f} < {min_alphanumeric_ratio})"

    return True, "pass"


def filter_quality_records(records: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Filters a batch of records, retaining only high-quality samples."""
    clean_records = []
    for rec in records:
        content = rec.get("content", "")
        passed, _ = is_high_quality_code(content)
        if passed:
            clean_records.append(rec)
    return clean_records


if __name__ == "__main__":
    normal_code = """
    def add(a: int, b: int) -> int:
        \"\"\"Return the sum of two integers.\"\"\"
        return a + b
    """

    minified_code = "var a=1;var b=2;function c(d,e){return d+e};" * 50

    print("Normal code quality:", is_high_quality_code(normal_code))
    print("Minified code quality:", is_high_quality_code(minified_code))
